<style>
/* ============ Tokens ============ */
:root[data-theme="dark"]{
  --bg:#12151b; --bg-2:#0d0f14;
  --panel:#1a1e27; --panel-2:#20242f; --panel-3:#252a36;
  --border:#2b3040; --border-soft:#232733;
  --text:#e9e6dc; --text-dim:#a6acbb; --text-faint:#6b7180;
  --accent:#e8a33d; --accent-soft:#3a2f1c;
  --accent2:#3fa796; --accent2-soft:#122a27;
  --danger:#d4695f; --danger-soft:#2c1a19;
  --ok:#6fbf8b; --ok-soft:#152820;
  --code-bg:#0d0f14; --code-text:#d7dbe6;
  --shadow: 0 12px 32px rgba(0,0,0,.35);
  --radius-sm:4px; --radius-md:8px; --radius-lg:14px;
}
:root[data-theme="light"]{
  --bg:#eef0f4; --bg-2:#e4e7ee;
  --panel:#ffffff; --panel-2:#f5f6fa; --panel-3:#eceef4;
  --border:#d8dce6; --border-soft:#e4e7ee;
  --text:#1c1f28; --text-dim:#565d6e; --text-faint:#8b91a1;
  --accent:#b9791f; --accent-soft:#fbeed9;
  --accent2:#1f7d6f; --accent2-soft:#dbf1ec;
  --danger:#b8443a; --danger-soft:#fbe4e2;
  --ok:#2f8a57; --ok-soft:#e2f4e9;
  --code-bg:#1c1f28; --code-text:#e9e6dc;
  --shadow: 0 12px 32px rgba(30,35,50,.12);
  --radius-sm:4px; --radius-md:8px; --radius-lg:14px;
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
@media (prefers-reduced-motion: reduce){ html{scroll-behavior:auto;} *{animation-duration:.001ms !important; transition-duration:.001ms !important;} }
body{
  margin:0; background:var(--bg); color:var(--text);
  font-family:'IBM Plex Sans', system-ui, sans-serif;
  font-size:16px; line-height:1.65;
}
h1,h2,h3,h4{ font-family:'Space Grotesk', system-ui, sans-serif; font-weight:600; letter-spacing:-.01em; color:var(--text); margin:0 0 .5em; }
a{color:var(--accent2);}
code, pre, .mono{ font-family:'IBM Plex Mono', monospace; }
p{margin:0 0 1em; max-width:74ch;}
::selection{ background:var(--accent); color:#1a1305; }
:focus-visible{ outline:2px solid var(--accent2); outline-offset:2px; border-radius:3px; }

/* ============ Top progress bar ============ */
#progressBar{ position:fixed; top:0; left:0; height:3px; width:0%; background:linear-gradient(90deg,var(--accent2),var(--accent)); z-index:200; transition:width .1s linear; }

/* ============ Top bar ============ */
.topbar{
  position:sticky; top:0; z-index:100;
  display:flex; align-items:center; gap:14px;
  padding:12px 20px; background:color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter:blur(10px); border-bottom:1px solid var(--border-soft);
}
.topbar .brand{ display:flex; align-items:center; gap:10px; font-family:'Space Grotesk'; font-weight:600; font-size:1.02rem; white-space:nowrap; }
.brand-mark{ width:26px;height:26px;border-radius:7px; background:conic-gradient(from 220deg, var(--accent2), var(--accent), var(--accent2)); flex:none; }
.search-wrap{ flex:1; max-width:420px; position:relative; }
.search-wrap input{
  width:100%; padding:9px 14px 9px 34px; border-radius:999px; border:1px solid var(--border);
  background:var(--panel-2); color:var(--text); font-family:'IBM Plex Sans'; font-size:.92rem;
}
.search-wrap input::placeholder{ color:var(--text-faint); }
.search-wrap svg{ position:absolute; left:11px; top:50%; transform:translateY(-50%); opacity:.6; width:15px;height:15px; }
.topbar-btn{
  display:inline-flex; align-items:center; gap:6px; padding:8px 14px; border-radius:999px;
  border:1px solid var(--border); background:var(--panel-2); color:var(--text); font-size:.86rem;
  cursor:pointer; white-space:nowrap; font-family:'IBM Plex Sans'; font-weight:500;
}
.topbar-btn:hover{ border-color:var(--accent2); }
#hamburger{ display:none; }

/* ============ Layout ============ */
.layout{ display:grid; grid-template-columns:270px minmax(0,1fr); max-width:1320px; margin:0 auto; }
.sidebar{
  position:sticky; top:53px; align-self:start; height:calc(100vh - 53px); overflow-y:auto;
  padding:22px 14px 40px; border-right:1px solid var(--border-soft);
}
.sidebar-progress{ padding:10px 10px 16px; }
.sidebar-progress-label{ font-size:.78rem; color:var(--text-dim); display:flex; justify-content:space-between; margin-bottom:6px;}
.sidebar-progress-track{ height:6px; border-radius:99px; background:var(--panel-3); overflow:hidden; }
.sidebar-progress-fill{ height:100%; width:0%; background:linear-gradient(90deg,var(--accent2),var(--accent)); transition:width .3s ease; }
.nav-list{ list-style:none; margin:0; padding:0; }
.nav-link{
  display:flex; align-items:center; gap:10px; padding:8px 10px; border-radius:8px;
  color:var(--text-dim); text-decoration:none; font-size:.89rem; cursor:pointer;
}
.nav-link:hover{ background:var(--panel-2); color:var(--text); }
.nav-link.active{ background:var(--accent-soft); color:var(--accent); }
.nav-num{ font-family:'IBM Plex Mono'; font-size:.72rem; color:var(--text-faint); width:18px; flex:none; }
.nav-link.active .nav-num{ color:var(--accent); }
.nav-title{ flex:1; }
.nav-dot{
  width:9px; height:9px; border-radius:50%; border:1.5px solid var(--border); flex:none; cursor:pointer;
}
.nav-dot.read{ background:var(--ok); border-color:var(--ok); }
