.hero p.lede{ font-size:1.08rem; color:var(--text-dim); max-width:62ch; }
.hero-grid{ display:grid; grid-template-columns:1.1fr .9fr; gap:40px; align-items:center; margin-top:30px;}
@media (max-width:900px){ .hero-grid{ grid-template-columns:1fr; } }

/* Live HTTP demo */
.demo{
