  padding:22px; box-shadow:var(--shadow);
}
.demo-title{ font-size:.82rem; color:var(--text-faint); margin-bottom:14px; font-family:'IBM Plex Mono'; }
.demo-track{ position:relative; height:64px; margin:6px 0 18px; }
.demo-node{
  position:absolute; top:50%; transform:translateY(-50%); width:78px; height:52px; border-radius:10px;
  background:var(--panel-2); border:1px solid var(--border); display:flex; flex-direction:column; align-items:center; justify-content:center; font-size:.72rem; color:var(--text-dim);
}
.demo-node.client{ left:0; } .demo-node.server{ right:0; }
.demo-node svg{ width:20px; height:20px; margin-bottom:3px; opacity:.85; }
.demo-line{ position:absolute; left:78px; right:78px; top:50%; height:2px; background:var(--border); transform:translateY(-50%); }
.demo-packet{
  position:absolute; top:50%; left:78px; transform:translate(0,-50%); width:11px;height:11px; border-radius:50%;
  background:var(--accent2); box-shadow:0 0 10px var(--accent2); opacity:0;
}
.demo-status{ position:absolute; top:-26px; right:78px; font-family:'IBM Plex Mono'; font-size:.78rem; padding:2px 8px; border-radius:6px; opacity:0; }
.demo-controls{ display:flex; gap:8px; flex-wrap:wrap; }
.demo-btn{
  padding:8px 12px; border-radius:8px; border:1px solid var(--border); background:var(--panel-2);
  color:var(--text); font-size:.82rem; cursor:pointer; font-family:'IBM Plex Mono';
}
.demo-btn:hover{ border-color:var(--accent2); color:var(--accent2); }
.demo-log{ margin-top:14px; font-family:'IBM Plex Mono'; font-size:.78rem; color:var(--text-dim); min-height:1.4em; }

