.chapter{ scroll-margin-top:70px; padding-top:8px; margin-bottom:56px; }
.chapter-head{ display:flex; align-items:baseline; gap:14px; margin-bottom:6px; }
.chapter-num{ font-family:'IBM Plex Mono'; color:var(--accent); font-size:1rem; }
.chapter-head h2{ font-size:1.7rem; margin:0; }
.chapter-intro{ color:var(--text-dim); font-size:1.02rem; margin-bottom:26px; }

/* topic cards (native details/summary) */
details.topic{
  background:var(--panel); border:1px solid var(--border-soft); border-radius:var(--radius-md);
  margin-bottom:12px; padding:0; overflow:hidden;
}
details.topic[open]{ border-color:var(--border); }
details.topic summary{
  list-style:none; cursor:pointer; padding:15px 18px; display:flex; align-items:center; gap:10px;
  font-family:'Space Grotesk'; font-weight:600; font-size:1.04rem; color:var(--text);
}
details.topic summary::-webkit-details-marker{ display:none; }
.chevron{ width:9px; height:9px; border-right:2px solid var(--text-faint); border-bottom:2px solid var(--text-faint); transform:rotate(-45deg); transition:transform .18s ease; flex:none; }
details.topic[open] .chevron{ transform:rotate(45deg); }
.topic-body{ padding:2px 18px 20px; color:var(--text); }
.topic-body p{ color:var(--text); }
.topic-body p.dim{ color: var(--text-dim); }

/* callouts */
.callout{ border-radius:var(--radius-md); padding:14px 16px; margin:16px 0; border-left:3px solid; font-size:.94rem; }
.callout p:last-child{ margin-bottom:0; }
.callout-label{ font-family:'IBM Plex Mono'; font-size:.72rem; text-transform:uppercase; letter-spacing:.06em; margin-bottom:6px; display:block; font-weight:600;}
.callout.tip{ background:var(--accent2-soft); border-color:var(--accent2); }
.callout.tip .callout-label{ color:var(--accent2); }
.callout.warn{ background:var(--danger-soft); border-color:var(--danger); }
.callout.warn .callout-label{ color:var(--danger); }
.callout.ask{ background:var(--accent-soft); border-color:var(--accent); }
.callout.ask .callout-label{ color:var(--accent); }

/* tables */
table{ width:100%; border-collapse:collapse; margin:16px 0; font-size:.9rem; }
th,td{ text-align:left; padding:9px 12px; border-bottom:1px solid var(--border-soft); vertical-align:top;}
th{ color:var(--text-dim); font-weight:600; font-family:'IBM Plex Mono'; font-size:.76rem; text-transform:uppercase; letter-spacing:.04em; }
