}
pre code{ background:none; padding:0; color:inherit; }
.tok-key{color:#e8a33d;} .tok-str{color:#8fc97a;} .tok-com{color:#7d8394; font-style:italic;} .tok-fn{color:#7ec8e3;} .tok-num{color:#c99bf0;}

/* mermaid */
.diagram{ background:#161a22; border:1px solid #2b3040; border-radius:var(--radius-lg); padding:18px; margin:18px 0; overflow-x:auto; }
.diagram-caption{ text-align:center; font-size:.78rem; color:var(--text-faint); margin-top:8px; font-family:'IBM Plex Mono'; }

/* quickcheck (self test reveal) */
.quickcheck{ border:1px dashed var(--border); border-radius:var(--radius-md); padding:14px 16px; margin:18px 0; }
.quickcheck-q{ font-weight:600; margin-bottom:6px; }
.quickcheck-reveal-btn{ background:none; border:1px solid var(--border); color:var(--accent2); padding:5px 11px; border-radius:7px; font-size:.8rem; cursor:pointer; font-family:'IBM Plex Mono';}
.quickcheck-a{ margin-top:10px; color:var(--text-dim); display:none; padding-top:10px; border-top:1px solid var(--border-soft); }
.quickcheck-a.shown{ display:block; }

/* chip lists */
.chips{ display:flex; flex-wrap:wrap; gap:8px; margin:14px 0; }
.chip{ padding:5px 12px; border-radius:999px; background:var(--panel-3); border:1px solid var(--border-soft); font-size:.8rem; font-family:'IBM Plex Mono'; color:var(--text-dim); }

/* comparison grid */
.vs-grid{ display:grid; grid-template-columns:1fr 1fr; gap:14px; margin:16px 0; }
@media (max-width:640px){ .vs-grid{ grid-template-columns:1fr; } }
.vs-card{ background:var(--panel-2); border:1px solid var(--border-soft); border-radius:var(--radius-md); padding:14px 16px; }
.vs-card h4{ font-size:.92rem; margin-bottom:8px; color:var(--accent2); }
.vs-card.b h4{ color:var(--accent); }
.vs-card ul{ margin:0; padding-left:18px; }
.vs-card li{ margin-bottom:4px; font-size:.9rem; color:var(--text-dim); }

/* flashcards modal */
#flashModal{ position:fixed; inset:0; background:rgba(0,0,0,.6); display:none; align-items:center; justify-content:center; z-index:300; padding:20px;}
#flashModal.open{ display:flex; }
.flash-wrap{ width:100%; max-width:520px; }
.flash-card{
  perspective:1200px; height:260px; cursor:pointer;
}
.flash-inner{ position:relative; width:100%; height:100%; transform-style:preserve-3d; transition:transform .5s cubic-bezier(.4,.2,.2,1); }
.flash-card.flipped .flash-inner{ transform:rotateY(180deg); }
.flash-face{
  position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-lg); border:1px solid var(--border);
  display:flex; align-items:center; justify-content:center; text-align:center; padding:30px; font-size:1.08rem;
  background:var(--panel); box-shadow:var(--shadow);
}
.flash-face.back{ transform:rotateY(180deg); background:var(--panel-2); color:var(--text-dim); font-size:.98rem;}
.flash-tag{ position:absolute; top:14px; left:16px; font-family:'IBM Plex Mono'; font-size:.7rem; color:var(--text-faint); }
.flash-controls{ display:flex; justify-content:space-between; align-items:center; margin-top:16px; }
.flash-controls .demo-btn{ background:var(--panel); }
.flash-count{ font-family:'IBM Plex Mono'; font-size:.8rem; color:var(--text-faint); }
.flash-close{ position:absolute; top:16px; right:20px; background:none; border:none; color:var(--text-dim); font-size:1.4rem; cursor:pointer; }

/* footer nav */
.chapter-footer-nav{ display:flex; justify-content:space-between; margin-top:10px; padding-top:16px; border-top:1px solid var(--border-soft); }
.footer-nav-btn{ font-size:.85rem; color:var(--text-dim); text-decoration:none; border:1px solid var(--border); padding:8px 14px; border-radius:8px; }
.footer-nav-btn:hover{ border-color:var(--accent2); color:var(--accent2); }

/* mobile */
@media (max-width:900px){
  .layout{ grid-template-columns:1fr; }
  .sidebar{ position:fixed; left:0; top:53px; width:270px; background:var(--bg); z-index:150; transform:translateX(-100%); transition:transform .25s ease; box-shadow:var(--shadow); }
  .sidebar.open{ transform:translateX(0); }
  #hamburger{ display:inline-flex; }
  .search-wrap{ display:none; }
  .content{ padding:0 18px 80px; }
  .hero h1{ font-size:2rem; }
}
.no-results{ color:var(--text-faint); font-style:italic; padding:30px 10px; display:none; }
</style>
</head>
